#define main legacy_main
#include "convolution3D-cuda/main.cu"
#undef main
#include <vector>
int main(){const int N=2,C=3,M=5,Win=37,Hin=35,K=3,Hout=33,Wout=35,WG=3,Z=9,S=N*M*Hout*Wout;std::vector<float>x(N*C*Hin*Win),w(M*C*K*K),want(S),out(S);for(int i=0;i<int(x.size());i++)x[i]=i%17-8;for(int i=0;i<int(w.size());i++)w[i]=i%13-6;for(int n=0;n<N;n++)for(int m=0;m<M;m++)for(int h=0;h<Hout;h++)for(int col=0;col<Wout;col++){long sum=0;for(int c=0;c<C;c++)for(int p=0;p<K;p++)for(int q=0;q<K;q++){int xi=((n*C+c)*Hin+h+p)*Win+col+q,wi=((m*C+c)*K+p)*K+q;sum+=(xi%17-8)*(wi%13-6);}want[((n*M+m)*Hout+h)*Wout+col]=sum;}float*X,*W,*Y;cudaMalloc(&X,x.size()*4);cudaMalloc(&W,w.size()*4);cudaMalloc(&Y,S*4);cudaMemcpy(X,x.data(),x.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(W,w.data(),w.size()*4,cudaMemcpyHostToDevice);auto run=[&](int style){if(style==1)conv3d_s1<<<dim3(N,M,Z),dim3(16,16)>>>(X,W,Y,C,M,K,Hin,Win,Hout,Wout,WG);else if(style==2)conv3d_s2<<<dim3(M,Z,N),dim3(16,16)>>>(X,W,Y,C,M,K,Hin,Win,Hout,Wout,WG);else conv3d_s3<<<dim3(Z,N,M),dim3(16,16)>>>(X,W,Y,C,M,K,Hin,Win,Hout,Wout,WG);};for(int style=1;style<=3;style++)run(style);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;for(int trial=1;trial<=5;trial++){double total=0,err=0;bool ok=true;std::vector<float>got;for(int style=1;style<=3;style++){std::fill(out.begin(),out.end(),-1.f);cudaMemcpy(Y,out.data(),S*4,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<10;rep++)run(style);if(cudaDeviceSynchronize()!=cudaSuccess)return 2;total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/10;cudaMemcpy(out.data(),Y,S*4,cudaMemcpyDeviceToHost);for(int i=0;i<S;i++){err=std::max(err,double(fabs(out[i]-want[i])));ok=ok&&std::isfinite(out[i])&&fabs(out[i]-want[i])<=1e-3f;}got.insert(got.end(),out.begin(),out.end());}char path[64];snprintf(path,64,"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(got.data(),4,got.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.15g,\"correct\":%s,\"checked_values\":34650,\"max_abs_error\":%.15g,\"timing_region\":\"sum_three_native_grid_order_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":10,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":34650,\"byte_order\":\"little\"}}\n",trial,total,ok?"true":"false",err,path);if(!ok)return 1;}cudaFree(X);cudaFree(W);cudaFree(Y);}
